 "content": "from collections import Counter

def transform(grid):
    counts = Counter(v for row in grid for v in row)
    # The background is noisy and uses the four recurring noise colors;
    # the salient foreground color is the most frequent remaining color.
    color = max((n, c) for c, n in counts.items() if c not in (0, 6, 7, 8, 9))[1]
    return [[color] * 3 for _ in range(3)]
